record GeoLocation(double lat, double lng) {}

interface IParkingLot {                       // shared contract (Composite)
    Optional<ParkingTicket> park(Vehicle v);
    int availableCount();
}

class ParkingLot implements IParkingLot { /* unchanged single-lot logic */ }

class ParkingLotNetwork implements IParkingLot {
    private final Map<String, ParkingLot> lots = new HashMap<>();

    // Cross-location operation the single lot never needed
    Optional<ParkingLot> nearestWithSpace(GeoLocation user, SpotSize size) {
        return lots.values().stream()
            .filter(l -> l.availableCount() > 0)
            .min(Comparator.comparingDouble(l -> distance(user, l.location())));
    }
    public Optional<ParkingTicket> park(Vehicle v) {            // delegate to a lot
        return lots.values().stream().map(l -> l.park(v))
                   .filter(Optional::isPresent).map(Optional::get).findFirst();
    }
    public int availableCount() {
        return lots.values().stream().mapToInt(ParkingLot::availableCount).sum();
    }
}
```
*`ParkingLot` is untouched — the network only aggregates and delegates.*

