class ParkingLot {                                  // Singleton
    private static ParkingLot instance;
    private final List<Observer> boards = new ArrayList<>();
    private FeeCalculator feeCalculator;            // Strategy
    private ParkingLot() {}
    static synchronized ParkingLot getInstance() {
        if (instance == null) instance = new ParkingLot();
        return instance;
    }
    void register(Observer o) { boards.add(o); }    // Observer
    void notifyBoards(ParkingSpot s) { boards.forEach(b -> b.update(s)); }
}

class VehicleFactory {                              // Factory Method
    static Vehicle create(VehicleType t, String plate) {
        return switch (t) {
            case CAR        -> new Car(plate);
            case MOTORCYCLE -> new Motorcycle(plate);
            case TRUCK      -> new Truck(plate);
        };
    }
}
